<div class="row justify-content-center"><div class="col-lg-7"><h1 class="h2">Verify membership</h1><p class="lead">Confirm an active ISHEP membership using its membership number.</p><form method="get" action="<?=e(url('/verify-membership'))?>" class="card shadow-sm mb-4"><div class="card-body"><label class="form-label" for="number">Membership number</label><input class="form-control" id="number" name="number" value="<?=e($number)?>" placeholder="ISH-MEM-2026-..."><div class="form-text">Only active membership status, type and validity are disclosed.</div></div><div class="card-footer bg-white text-end"><button class="btn btn-primary">Verify</button></div></form><?php if($result&&isset($result['throttled'])):?><div class="alert alert-warning">Too many verification attempts. Try again in about 60 seconds.</div><?php elseif($searched&&$result):?><div class="alert alert-success"><h2 class="h5">Active membership verified</h2><dl class="row mb-0"><dt class="col-sm-4">Membership number</dt><dd class="col-sm-8"><?=e($result['membership_number'])?></dd><dt class="col-sm-4">Membership type</dt><dd class="col-sm-8"><?=e($result['membership_type_name'])?></dd><dt class="col-sm-4">Valid from</dt><dd class="col-sm-8"><?=e($result['starts_at']?:'Not recorded')?></dd><dt class="col-sm-4">Valid until</dt><dd class="col-sm-8"><?=e($result['expires_at']?:'Not recorded')?></dd></dl></div><?php elseif($searched):?><div class="alert alert-danger">No active membership was found for that number.</div><?php endif;?></div></div>